SELECT Имена_ОЭС.nameoes, Имена_областей.NAME AS область, Имена_станций.NAME, [Станции(архив)].year, [Станции(архив)].nust, [Станции(архив)].E, [Станции(архив)].ewtp, [Станции(архив)].Q, [Станции(архив)].qotr, [Станции(архив)].B, [Станции(архив)].gaz, [Станции(архив)].mazut, [Станции(архив)].torf, [Станции(архив)].slan, [Станции(архив)].proch, [Станции(архив)].ugol, [Станции(архив)].numb1120, [Станции(архив)].numb1, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип, [Станции(архив)].eust, [Станции(архив)].tust
FROM (([Станции(архив)] LEFT JOIN Имена_станций ON [Станции(архив)].numb1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON [Станции(архив)].oes=Имена_ОЭС.oes) INNER JOIN Имена_областей ON [Станции(архив)].obl=Имена_областей.OBL;
